ALTER TABLE "founder_checkout_correlations" DROP CONSTRAINT "founder_checkout_correlations_consumed_check";--> statement-breakpoint
ALTER TABLE "founder_checkout_correlations" DROP CONSTRAINT "founder_checkout_correlations_closed_check";--> statement-breakpoint
ALTER TABLE "founder_checkout_correlations" ADD CONSTRAINT "founder_checkout_correlations_consumed_check" CHECK (("founder_checkout_correlations"."status" = 'pending' AND "founder_checkout_correlations"."consumed_at" IS NULL AND "founder_checkout_correlations"."closed_at" IS NULL AND "founder_checkout_correlations"."closure_reason" IS NULL) OR ("founder_checkout_correlations"."status" IN ('consumed', 'refund_pending') AND "founder_checkout_correlations"."consumed_at" IS NOT NULL AND "founder_checkout_correlations"."closed_at" IS NULL AND "founder_checkout_correlations"."closure_reason" IS NULL) OR ("founder_checkout_correlations"."status" = 'closed' AND "founder_checkout_correlations"."closed_at" IS NOT NULL AND "founder_checkout_correlations"."closure_reason" IS NOT NULL AND ("founder_checkout_correlations"."consumed_at" IS NOT NULL OR "founder_checkout_correlations"."closure_reason" = 'account_closure')));--> statement-breakpoint
ALTER TABLE "founder_checkout_correlations" ADD CONSTRAINT "founder_checkout_correlations_closed_check" CHECK ("founder_checkout_correlations"."status" <> 'closed' OR ("founder_checkout_correlations"."closure_reason" IN ('payment_without_access_refunded', 'payment_without_access_refunded_superseded') AND "founder_checkout_correlations"."refunded_at" IS NOT NULL) OR ("founder_checkout_correlations"."closure_reason" = 'account_closure' AND "founder_checkout_correlations"."consumed_at" IS NULL AND "founder_checkout_correlations"."refunded_at" IS NULL));